import React from "react";
import "./FileUpload.scss";
export interface FileUploadProps {
    /**
     * Identifying value for the chip.
     */
    id: string;
    /**
     * Text value to be displayed next to the file upload.
     */
    label: string;
    /**
     * Progress of the file upload in percentage.
     */
    progress?: Record<string, number>;
    /**
     * Determines the colour palette of the file upload.
     */
    colour?: "primary" | "secondary" | "tertiary";
    /**
     * Text value to be displayed at file upload.
     */
    uploadMessage: string;
    /**
    * Accepted file type.
    */
    fileType: string;
    /**
    * Text value to be displayed as warning message.
    */
    warningMessage: string;
    /**
     * Maximum file size accepted in MB.
     */
    fileSize: number;
    /**
     * Tooltip text to be displayed when hovering over the help icon.
     */
    tooltip?: string;
    /**
     * Maximum file count accepted.
     */
    maxFileCount?: number;
    /**
     * File type icon shown with progress bar.
     */
    progressBarIcon?: string;
    /**
     * Custom error message shown if incorrect file type.
     */
    uploadTypeErrorMessage?: string;
    /**
     * Callback function to return valid files.
     * @param files
     * @returns
     */
    onFilesChange?: (files: UploadFile[]) => void;
    onInvalidFiles?: (files: UploadFile[]) => void;
    onDeleteFiles?: (file: UploadFile) => void;
    onDeleteErrorFiles?: (file: UploadFile) => void;
    /**
     * Initial/default files to display when component mounts.
     * Useful for restoring files when navigating back to a form.
     */
    defaultFiles?: UploadFile[];
    uploadSucessMessage?: string;
}
export interface UploadFile {
    file: File;
    fileId: string;
    error?: string;
    isVisible: boolean;
}
declare const FileUpload: React.FC<FileUploadProps>;
export default FileUpload;
